522:   /// fn init<R: Runtime>() -> TauriPlugin<R> {
523:   ///   Builder::new("example")
524:   ///     .on_webview_ready(|webview| {
525:   ///       println!("created webview {}", webview.label());
526:   ///     })
527:   ///     .build()
528:   /// }
529:   /// ```
